-- Additive identity history and private relationships. No world, asset, transcript or central row is rewritten.
CREATE TABLE IF NOT EXISTS character_identity_versions(id TEXT PRIMARY KEY,character_id TEXT NOT NULL,number INTEGER NOT NULL CHECK(typeof(number)='integer' AND number BETWEEN 0 AND 9007199254740991),catalog_version INTEGER NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,type TEXT NOT NULL,identity TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','published')),created_by TEXT,created_at TEXT NOT NULL,published_at TEXT,request_hash TEXT NOT NULL DEFAULT '',UNIQUE(character_id,number));
CREATE TABLE IF NOT EXISTS character_identity_policies(character_id TEXT PRIMARY KEY,active_version_id TEXT NOT NULL REFERENCES character_identity_versions(id),scope TEXT NOT NULL DEFAULT 'all' CHECK(scope IN('all','new')),revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 9007199254740991),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS character_version_assignments(owner_id TEXT NOT NULL,owner_kind TEXT NOT NULL,subject_id TEXT NOT NULL,character_id TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES character_identity_versions(id),assigned_at TEXT NOT NULL,PRIMARY KEY(owner_id,character_id));
CREATE INDEX IF NOT EXISTS character_assignment_subject ON character_version_assignments(subject_id,owner_kind);
CREATE TABLE IF NOT EXISTS character_identity_publications(id TEXT PRIMARY KEY,character_id TEXT NOT NULL,version_id TEXT NOT NULL,previous_version_id TEXT NOT NULL,scope TEXT NOT NULL,actor_id TEXT NOT NULL,affected_owners INTEGER NOT NULL,created_at TEXT NOT NULL,request_hash TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS character_relationships(owner_id TEXT NOT NULL,owner_kind TEXT NOT NULL,subject_id TEXT NOT NULL,character_id TEXT NOT NULL,epoch INTEGER NOT NULL DEFAULT 0 CHECK(typeof(epoch)='integer' AND epoch BETWEEN 0 AND 9007199254740991),blocked_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,character_id));
CREATE TABLE IF NOT EXISTS character_memories(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,character_id TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL CHECK(length(content)<=600),content_hash TEXT NOT NULL,source_hash TEXT NOT NULL,source_prefix_hash TEXT NOT NULL,source_ref TEXT NOT NULL,world_id TEXT NOT NULL,point_id TEXT NOT NULL,confirmation TEXT NOT NULL CHECK(confirmation IN('explicit','user-confirmed')),confidence REAL NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 9007199254740991),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(owner_id,character_id,content_hash),FOREIGN KEY(owner_id,character_id) REFERENCES character_relationships(owner_id,character_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS character_memory_owner ON character_memories(owner_id,character_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS character_memory_suppressions(owner_id TEXT NOT NULL,character_id TEXT NOT NULL,content_hash TEXT NOT NULL,source_hash TEXT NOT NULL,source_prefix_hash TEXT NOT NULL,PRIMARY KEY(owner_id,character_id,content_hash),FOREIGN KEY(owner_id,character_id) REFERENCES character_relationships(owner_id,character_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS character_memory_context_boundaries(owner_id TEXT NOT NULL,character_id TEXT NOT NULL,world_id TEXT NOT NULL,conversation_key TEXT NOT NULL,message_count INTEGER NOT NULL,PRIMARY KEY(owner_id,character_id,world_id,conversation_key),FOREIGN KEY(owner_id,character_id) REFERENCES character_relationships(owner_id,character_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS character_memory_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,character_id TEXT NOT NULL,epoch INTEGER NOT NULL,source_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','done','failed')),created_at TEXT NOT NULL,UNIQUE(owner_id,character_id,source_hash),FOREIGN KEY(owner_id,character_id) REFERENCES character_relationships(owner_id,character_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS character_mutation_limits(owner_id TEXT NOT NULL,minute INTEGER NOT NULL,mutations INTEGER NOT NULL,PRIMARY KEY(owner_id,minute));
INSERT OR IGNORE INTO character_identity_versions(id,character_id,number,catalog_version,name,description,type,identity,state,created_by,created_at,published_at) SELECT 'baseline:'||id,id,0,version,name,description,type,'{}','published',NULL,created_at,created_at FROM central_characters;
INSERT OR IGNORE INTO character_identity_policies SELECT id,'baseline:'||id,'all',1,updated_at FROM central_characters;
CREATE TRIGGER IF NOT EXISTS character_identity_immutable BEFORE UPDATE ON character_identity_versions WHEN OLD.state='published' AND (NEW.identity<>OLD.identity OR NEW.name<>OLD.name OR NEW.description<>OLD.description OR NEW.type<>OLD.type OR NEW.character_id<>OLD.character_id OR NEW.number<>OLD.number OR NEW.state<>OLD.state OR NEW.catalog_version<>OLD.catalog_version) BEGIN SELECT RAISE(ABORT,'published_identity_immutable'); END;
CREATE TRIGGER IF NOT EXISTS character_member_cleanup AFTER DELETE ON user_accounts BEGIN DELETE FROM character_relationships WHERE owner_kind='member' AND subject_id=OLD.id; DELETE FROM character_version_assignments WHERE owner_kind='member' AND subject_id=OLD.id; END;
CREATE TRIGGER IF NOT EXISTS character_admin_cleanup AFTER DELETE ON admins BEGIN DELETE FROM character_relationships WHERE owner_kind='admin' AND subject_id=OLD.id; DELETE FROM character_version_assignments WHERE owner_kind='admin' AND subject_id=OLD.id; END;
